// Timers on priorities, with every callback run inside the error guard and
// the timing logged, like the reference's scheduler-aware timer modules.
import { applyWithGuard } from "ErrorGuard";
import { track } from "Workload";

const active = new Map();
let nextId = 1;

export function setTimeoutGuarded(callback, delay, name = callback.name) {
  const id = nextId++;
  let resolveTracked;
  track(new Promise((resolve) => (resolveTracked = resolve)));
  const handle = setTimeout(() => {
    active.delete(id);
    applyWithGuard(callback, null, [], { name: `timer:${name}` });
    resolveTracked();
  }, delay);
  active.set(id, { handle, resolve: resolveTracked });
  return id;
}

export function clearTimeoutGuarded(id) {
  const timer = active.get(id);
  if (timer) {
    clearTimeout(timer.handle);
    timer.resolve();
    active.delete(id);
  }
}

// In benchmark mode, hover-intent and debounce timers aren't left to run:
// the step flushes them explicitly. Each pending deferred call is kept here.
const deferred = new Map();

export function deferUntilFlush(key, callback) {
  deferred.set(key, callback);
}

export function cancelDeferred(key) {
  deferred.delete(key);
}

export function flushDeferred(key) {
  const keys = key ? [key] : [...deferred.keys()];
  for (const k of keys) {
    const callback = deferred.get(k);
    if (callback) {
      deferred.delete(k);
      applyWithGuard(callback, null, [], { name: `deferred:${k}` });
    }
  }
}
