// The page's single React root: the Relay environment, the theme, the
// logging surface, the router, and the header above whatever page the route
// shows, with the post dialog over it.
import { Suspense, useMemo } from "react";
import { RelayEnvironmentProvider } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors, type } from "BaseTokens.stylex";
import RelayEnvironment from "RelayEnvironment";
import { ThemeContext, TypeScaleContext, VisualCompletionContext } from "UIContexts";
import LoggingSurface from "LoggingSurface.react";
import UIErrorBoundary from "UIErrorBoundary.react";
import SiteRouter from "SiteRouter.react";
import TopNav from "TopNav.react";
import LazyModule from "LazyModule.react";

const styles = stylex.create({
  app: { minHeight: "100vh", backgroundColor: colors.webWash, color: colors.primaryText, fontFamily: type.fontFamily },
});

function Shell({ topNavQuery, page, dialog }) {
  return (
    <>
      <UIErrorBoundary name="top_nav">
        <Suspense fallback={null}>
          <TopNav queryRef={topNavQuery} />
        </Suspense>
      </UIErrorBoundary>
      <UIErrorBoundary name="page">
        <Suspense fallback={null}>{page}</Suspense>
      </UIErrorBoundary>
      {dialog?.kind === "post" ? (
        <UIErrorBoundary name="post_dialog">
          <Suspense fallback={null}>
            <LazyModule name="PostDialog.react" props={{ storyId: dialog.storyId }} />
          </Suspense>
        </UIErrorBoundary>
      ) : null}
    </>
  );
}

export default function SocialFeedRoot({ topNavQuery, initialUrl, initialEntryPointReference }) {
  const theme = useMemo(() => ({ name: "light", className: null }), []);
  const visualCompletion = useMemo(() => ({ ignore: false }), []);
  return (
    <RelayEnvironmentProvider environment={RelayEnvironment}>
      <ThemeContext.Provider value={theme}>
        <TypeScaleContext.Provider value="default">
          <VisualCompletionContext.Provider value={visualCompletion}>
            <LoggingSurface name="root">
              <div {...stylex.props(styles.app)}>
                <SiteRouter initialUrl={initialUrl} initialEntryPointReference={initialEntryPointReference} renderShell={(page, dialog) => <Shell topNavQuery={topNavQuery} page={page} dialog={dialog} />} />
              </div>
            </LoggingSurface>
          </VisualCompletionContext.Provider>
        </TypeScaleContext.Provider>
      </ThemeContext.Provider>
    </RelayEnvironmentProvider>
  );
}
