// Flex layout primitives used everywhere: UIRow and UIColumn with spacing
// tokens, alignment and wrapping.
import * as stylex from "@stylexjs/stylex";
import { spacing } from "BaseTokens.stylex";

const styles = stylex.create({
  row: { display: "flex", flexDirection: "row", minWidth: 0 },
  column: { display: "flex", flexDirection: "column", minWidth: 0 },
  gap: (gap) => ({ gap }),
  alignStart: { alignItems: "flex-start" },
  alignCenter: { alignItems: "center" },
  alignEnd: { alignItems: "flex-end" },
  alignStretch: { alignItems: "stretch" },
  justifyStart: { justifyContent: "flex-start" },
  justifyCenter: { justifyContent: "center" },
  justifyEnd: { justifyContent: "flex-end" },
  justifyBetween: { justifyContent: "space-between" },
  wrap: { flexWrap: "wrap" },
  grow: { flexGrow: 1, flexShrink: 1, flexBasis: 0 },
  paddingSmall: { padding: spacing.s2 },
  paddingMedium: { padding: spacing.s4 },
  paddingLarge: { padding: spacing.s6 },
});

const ALIGN = { start: styles.alignStart, center: styles.alignCenter, end: styles.alignEnd, stretch: styles.alignStretch };
const JUSTIFY = { start: styles.justifyStart, center: styles.justifyCenter, end: styles.justifyEnd, between: styles.justifyBetween };
const PADDING = { small: styles.paddingSmall, medium: styles.paddingMedium, large: styles.paddingLarge };

function stackProps(direction, { gap = 0, align, justify, wrap, grow, padding, xstyle }) {
  return stylex.props(direction, gap > 0 && styles.gap(gap), align && ALIGN[align], justify && JUSTIFY[justify], wrap && styles.wrap, grow && styles.grow, padding && PADDING[padding], xstyle);
}

export function UIRow({ as: Tag = "div", children, gap, align = "center", justify, wrap, grow, padding, xstyle, ...rest }) {
  return (
    <Tag {...rest} {...stackProps(styles.row, { gap, align, justify, wrap, grow, padding, xstyle })}>
      {children}
    </Tag>
  );
}

export function UIColumn({ as: Tag = "div", children, gap, align, justify, wrap, grow, padding, xstyle, ...rest }) {
  return (
    <Tag {...rest} {...stackProps(styles.column, { gap, align, justify, wrap, grow, padding, xstyle })}>
      {children}
    </Tag>
  );
}
