// Renders its children into the page's layer container (for popovers,
// menus, dialogs and tooltips) through a portal.
import { useContext, useMemo } from "react";
import { createPortal } from "react-dom";
import { LayerContext } from "UIContexts";

export default function UILayer({ children }) {
  const parent = useContext(LayerContext);
  const container = parent.container ?? document.getElementById("layers");
  const value = useMemo(() => ({ container, depth: parent.depth + 1 }), [container, parent.depth]);
  return createPortal(<LayerContext.Provider value={value}>{children}</LayerContext.Provider>, container);
}
