// Renders a component from a module that may still have to be loaded,
// suspending until it is.
import JSResource from "JSResource";

export default function LazyModule({ name, props }) {
  const resource = JSResource(name);
  const module = resource.getModuleIfRequired();
  if (module === null) {
    throw resource.load();
  }
  const Component = module.default ?? module;
  return <Component {...props} />;
}
