// A link that navigates within the app through the router, or opens an
// external page.
import { useContext } from "react";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { RouterContext } from "RouterContext";
import UIPressable from "UIPressable.react";

const styles = stylex.create({
  base: { display: "inline", color: "inherit", textDecoration: { default: "none", ":hover": "underline" }, borderRadius: 2 },
  link: { color: colors.blueLink },
  strong: { fontWeight: 600 },
  block: { display: "block", textDecoration: "none" },
});

export default function UILink({ href, children, color = "inherit", strong = false, block = false, label, onPress, testid, xstyle }) {
  const router = useContext(RouterContext);
  const external = /^https?:/.test(href ?? "");
  return (
    <UIPressable
      as="a"
      href={href}
      label={label}
      logName={label ?? "link"}
      testid={testid}
      showOverlay={false}
      onPress={(event) => {
        onPress?.(event);
        if (!external && href && router) {
          router.navigate(href);
        }
      }}
      xstyle={[styles.base, color === "link" && styles.link, strong && styles.strong, block && styles.block, xstyle]}
    >
      {children}
    </UIPressable>
  );
}
