import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { iconButtonTokens } from "ComponentTokens.stylex";
import UIPressable from "UIPressable.react";
import UIIcon from "UIIcon.react";
import UIBadge from "UIBadge.react";

const styles = stylex.create({
  base: { justifyContent: "center", borderRadius: radii.round, flexShrink: 0, transitionDuration: iconButtonTokens.transitionDuration },
  size: (size) => ({ width: size, height: size }),
  filled: { backgroundColor: colors.secondaryButtonBackground },
  selected: { backgroundColor: colors.accentAlpha20 },
  badge: { position: "absolute", top: -4, right: -4 },
});

export default function UIIconButton({ icon, label, size = 36, iconSize = 20, filled = true, selected = false, badgeCount = 0, onPress, testid, xstyle, ...rest }) {
  return (
    <UIPressable {...rest} label={label} logName={label} onPress={onPress} testid={testid} aria-pressed={selected || undefined} xstyle={[styles.base, styles.size(size), filled && styles.filled, selected && styles.selected, xstyle]}>
      <UIIcon name={icon} size={iconSize} color={selected ? "accent" : "primary"} filled={selected} />
      {badgeCount > 0 ? <UIBadge count={badgeCount} xstyle={styles.badge} /> : null}
    </UIPressable>
  );
}
