import * as stylex from "@stylexjs/stylex";
import { colors, type } from "BaseTokens.stylex";

const styles = stylex.create({
  base: {
    display: "inline-flex",
    alignItems: "center",
    justifyContent: "center",
    minWidth: 19,
    height: 19,
    paddingInline: 5,
    boxSizing: "border-box",
    borderRadius: 10,
    backgroundColor: colors.badgeBackground,
    color: "white",
    fontSize: type.captionSize,
    fontWeight: type.weightBold,
    lineHeight: "19px",
  },
});

export default function UIBadge({ count, xstyle }) {
  return <span {...stylex.props(styles.base, xstyle)}>{count > 99 ? "99+" : count}</span>;
}
