// Keeps a feed unit mounted while it's within a margin of the viewport, and
// collapses it to a placeholder of the same height when it's far outside,
// as the reference's feed does. An IntersectionObserver reports the changes
// after scrolling; refreshFeedVirtualization() checks every unit's geometry
// right away, which the benchmark steps call after they scroll instead of
// waiting a frame for the observer. The observer's root is the document:
// with the implicit root, a frame (as in Speedometer) clips the margin away,
// so the observer and refreshFeedVirtualization() disagreed about the units
// below the frame and the last one to run won.
import { useEffect, useRef, useState } from "react";

const MARGIN = 1600;
let observer = null;
const callbacks = new Map();

function getObserver() {
  if (observer === null) {
    observer = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          callbacks.get(entry.target)?.(entry.isIntersecting);
        }
      },
      { root: document, rootMargin: `${MARGIN}px 0px` },
    );
  }
  return observer;
}

export function refreshFeedVirtualization() {
  const height = window.innerHeight;
  for (const [element, callback] of callbacks) {
    const rect = element.getBoundingClientRect();
    callback(rect.bottom >= -MARGIN && rect.top <= height + MARGIN);
  }
}

export default function FeedVirtualizedUnit({ children, position }) {
  const ref = useRef(null);
  const height = useRef(0);
  const [visible, setVisible] = useState(true);
  useEffect(() => {
    const element = ref.current;
    callbacks.set(element, (isIntersecting) => {
      if (!isIntersecting && element.firstElementChild) {
        height.current = element.offsetHeight;
      }
      setVisible(isIntersecting);
    });
    getObserver().observe(element);
    return () => {
      getObserver().unobserve(element);
      callbacks.delete(element);
    };
  }, []);
  return (
    <div ref={ref} data-feed-position={position} style={visible ? undefined : { height: height.current }} data-visualcompletion={visible ? undefined : "ignore"}>
      {visible ? children : null}
    </div>
  );
}
