// The header: the wordmark and search on the left, the section tabs in the
// middle, and the menus on the right. Each menu's panel is a module loaded
// when it first opens.
import { Suspense, useCallback, useRef, useState } from "react";
import { graphql, usePreloadedQuery } from "react-relay";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import { navTabTokens } from "ComponentTokens.stylex";
import UIIconButton from "UIIconButton.react";
import UIIcon from "UIIcon.react";
import UILink from "UILink.react";
import UIAvatar from "UIAvatar.react";
import UIPressable from "UIPressable.react";
import UIPopover from "UIPopover.react";
import UISpinner from "UISpinner.react";
import { UIRow } from "UIStack.react";
import LoggingSurface from "LoggingSurface.react";
import Wordmark from "Wordmark.react";
import SearchBox from "SearchBox.react";
import LazyModule from "LazyModule.react";

const styles = stylex.create({
  bar: { position: "sticky", top: 0, zIndex: 20, height: 56, paddingInline: 16, display: "flex", alignItems: "center", justifyContent: "space-between", backgroundColor: colors.surfaceBackground, boxShadow: elevation.e1 },
  left: { gap: 8, flexBasis: 320, flexShrink: 0 },
  tabs: { gap: 8, flexGrow: 1, justifyContent: "center", height: "100%" },
  tab: { justifyContent: "center", width: 112, height: 48, borderRadius: navTabTokens.radius },
  tabSelected: { borderBottom: `3px solid ${colors.accent}`, borderRadius: 0 },
  right: { gap: 8, flexBasis: 320, flexShrink: 0, justifyContent: "flex-end" },
  loading: { display: "flex", justifyContent: "center", padding: 24 },
});

const TABS = [
  { key: "home", icon: "home", label: "Home", href: "/" },
  { key: "video", icon: "video", label: "Video", href: "/watch" },
  { key: "market", icon: "market", label: "Marketplace", href: "/marketplace" },
  { key: "groups", icon: "groups", label: "Groups", href: "/groups" },
  { key: "gaming", icon: "gaming", label: "Gaming", href: "/gaming" },
];

const PANELS = {
  menu: { module: "AppsMenuPanel.react", label: "Menu", width: 600 },
  messenger: { module: "MessengerPanel.react", label: "Messenger", width: 360 },
  notifications: { module: "NotificationsPanel.react", label: "Notifications", width: 360 },
  account: { module: "AccountMenuPanel.react", label: "Account", width: 360 },
};

function HeaderMenu({ panel, icon, label, badgeCount = 0, avatar = null, open, onToggle, onClose, testid }) {
  const anchor = useRef(null);
  const config = PANELS[panel];
  return (
    <span ref={anchor}>
      {avatar ? (
        <UIPressable label={label} onPress={onToggle} testid={testid} aria-expanded={open} xstyle={styles.tab}>
          <UIAvatar src={avatar} size={40} />
        </UIPressable>
      ) : (
        <UIIconButton icon={icon} label={label} size={40} selected={open} badgeCount={badgeCount} onPress={onToggle} testid={testid} aria-expanded={open} />
      )}
      {open ? (
        <UIPopover anchorRef={anchor} onClose={onClose} label={config.label} width={config.width} testid={`${panel}-panel`}>
          <Suspense
            fallback={
              <div {...stylex.props(styles.loading)}>
                <UISpinner />
              </div>
            }
          >
            <LazyModule name={config.module} props={{ onClose }} />
          </Suspense>
        </UIPopover>
      ) : null}
    </span>
  );
}

export default function TopNav({ queryRef }) {
  const data = usePreloadedQuery(
    graphql`
      query TopNavQuery @preloadable {
        viewer {
          actor {
            id
            name
            short_name
            url
            profile_picture(size: 40) {
              uri
            }
          }
          notifications_badge {
            count
          }
          messenger_badge {
            count
          }
        }
      }
    `,
    queryRef,
  );
  const [openPanel, setOpenPanel] = useState(null);
  const close = useCallback(() => setOpenPanel(null), []);
  const toggle = (panel) => () => setOpenPanel((current) => (current === panel ? null : panel));
  const viewer = data.viewer;
  return (
    <LoggingSurface name="top_nav">
      <div role="banner" {...stylex.props(styles.bar)}>
        <UIRow xstyle={styles.left}>
          <UILink href="/" label="Home">
            <Wordmark />
          </UILink>
          <SearchBox />
        </UIRow>
        <UIRow as="nav" aria-label="Sections" xstyle={styles.tabs}>
          {TABS.map((tab) => (
            <UILink key={tab.key} href={tab.href} label={tab.label} xstyle={[styles.tab, tab.key === "home" && styles.tabSelected]}>
              <UIIcon name={tab.icon} size={24} color={tab.key === "home" ? "accent" : "secondary"} />
            </UILink>
          ))}
        </UIRow>
        <UIRow xstyle={styles.right}>
          <HeaderMenu panel="menu" icon="grid" label="Menu" open={openPanel === "menu"} onToggle={toggle("menu")} onClose={close} testid="menu-button" />
          <HeaderMenu panel="messenger" icon="chat" label="Messenger" badgeCount={viewer?.messenger_badge?.count ?? 0} open={openPanel === "messenger"} onToggle={toggle("messenger")} onClose={close} testid="messenger-button" />
          <HeaderMenu panel="notifications" icon="bell" label="Notifications" badgeCount={viewer?.notifications_badge?.count ?? 0} open={openPanel === "notifications"} onToggle={toggle("notifications")} onClose={close} testid="notifications-button" />
          <HeaderMenu panel="account" label="Your profile" avatar={viewer?.actor?.profile_picture?.uri} open={openPanel === "account"} onToggle={toggle("account")} onClose={close} testid="account-button" />
        </UIRow>
      </div>
    </LoggingSurface>
  );
}
