// Boots the page. Hyperion's interceptors go in first, so that everything
// after runs through them. Opened on its own, the page renders right away;
// in the Speedometer frame, or with ?benchmark, it prepares (loads every
// package file and prepared response) and the first step renders.
import { createRoot } from "react-dom/client";
import { loadEntryPoint, loadQuery } from "react-relay";
import { installHyperion } from "HyperionSetup";
import { setupFbt } from "FbtSetup";
import { startVisualCompletion } from "VisualCompletion";
import { processInlinePayloads } from "ServerJS";
import { preloadAll } from "Bootloader";
import { preloadResponses } from "RelayResponseStore";
import { benchmarkMode } from "SiteConfig";
import RelayEnvironment from "RelayEnvironment";
import TopNavQuery$parameters from "TopNavQuery$parameters";
import HomePageEntryPoint from "HomePage.entrypoint";
import SocialFeedRoot from "SocialFeedRoot.react";
import { emitStepEvent, nextEvent, trackReactRoot, whenIdle } from "Workload";
import { flushDeferred } from "TimerGuard";
import { refreshFeedVirtualization } from "FeedVirtualizedUnit.react";
import PerfLogger from "PerfLogger";

let root = null;

function render() {
  PerfLogger.markerStart("page_render");
  processInlinePayloads();
  const container = document.getElementById("root");
  startVisualCompletion(document.body);
  const topNavQuery = loadQuery(RelayEnvironment, TopNavQuery$parameters, {});
  const initialEntryPointReference = loadEntryPoint({ getEnvironment: () => RelayEnvironment }, HomePageEntryPoint, {});
  root = createRoot(container);
  trackReactRoot(root);
  root.render(<SocialFeedRoot topNavQuery={topNavQuery} initialUrl="/" initialEntryPointReference={initialEntryPointReference} />);
  PerfLogger.markerEnd("page_render", "scheduled");
}

async function prepare() {
  await Promise.all([preloadAll(), preloadResponses(document.baseURI)]);
}

export function start() {
  history.replaceState({ url: "/" }, "");
  installHyperion();
  setupFbt();
  const ready = benchmarkMode ? prepare() : Promise.resolve();
  window.socialWorkload = { ready, render, whenIdle, nextEvent, flushDeferred, emitStepEvent, refreshFeedVirtualization };
  if (!benchmarkMode) {
    render();
  }
  return ready;
}
