// Keeps keyboard focus inside a dialog or menu, restores it on unmount, and
// optionally focuses the first tabbable element on mount.
import { useContext, useEffect, useMemo, useRef } from "react";
import { FocusScopeContext } from "UIContexts";

const TABBABLE = 'a[href],button:not([disabled]),input:not([disabled]),textarea,[tabindex="0"],[contenteditable="true"]';

export default function UIFocusScope({ children, autoFocus = false, trap = false, restoreFocus = true }) {
  const ref = useRef(null);
  const parent = useContext(FocusScopeContext);
  useEffect(() => {
    const previous = document.activeElement;
    const container = ref.current;
    if (autoFocus && container) {
      const first = container.querySelector(TABBABLE);
      first?.focus({ preventScroll: true });
    }
    const onKeyDown = (event) => {
      if (!trap || event.key !== "Tab" || !container) {
        return;
      }
      const tabbable = [...container.querySelectorAll(TABBABLE)];
      if (!tabbable.length) {
        return;
      }
      const first = tabbable[0];
      const last = tabbable[tabbable.length - 1];
      if (event.shiftKey && document.activeElement === first) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    container?.addEventListener("keydown", onKeyDown);
    return () => {
      container?.removeEventListener("keydown", onKeyDown);
      if (restoreFocus && previous instanceof HTMLElement && previous.isConnected) {
        previous.focus({ preventScroll: true });
      }
    };
  }, [autoFocus, trap, restoreFocus]);
  const value = useMemo(() => ({ parent, ref }), [parent]);
  return (
    <FocusScopeContext.Provider value={value}>
      <div ref={ref} style={{ display: "contents" }}>
        {children}
      </div>
    </FocusScopeContext.Provider>
  );
}
