// A popover placed next to its anchor: measures the anchor and the popover
// with getBoundingClientRect after mount, flips to stay in the viewport,
// and closes on Escape or an outside click.
import { useLayoutEffect, useEffect, useRef, useState } from "react";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { elevation } from "ElevationTokens.stylex";
import UILayer from "UILayer.react";
import UIFocusScope from "UIFocusScope.react";

const styles = stylex.create({
  base: { position: "fixed", zIndex: 30, backgroundColor: colors.popoverBackground, borderRadius: radii.lg, boxShadow: elevation.e4, overflow: "hidden", maxHeight: "calc(100vh - 72px)", overflowY: "auto", visibility: "hidden" },
  placed: { visibility: "visible" },
  width: (width) => ({ width }),
});

export default function UIPopover({ anchorRef, onClose, align = "end", width = 360, label, children, testid, autoFocus = true }) {
  const ref = useRef(null);
  const [position, setPosition] = useState(null);
  useLayoutEffect(() => {
    const anchor = anchorRef.current?.getBoundingClientRect();
    const popover = ref.current?.getBoundingClientRect();
    if (!anchor || !popover) {
      return;
    }
    const viewportWidth = document.documentElement.clientWidth;
    const viewportHeight = document.documentElement.clientHeight;
    let left = align === "end" ? anchor.right - popover.width : align === "center" ? anchor.left + anchor.width / 2 - popover.width / 2 : anchor.left;
    left = Math.max(8, Math.min(left, viewportWidth - popover.width - 8));
    let top = anchor.bottom + 6;
    if (top + popover.height > viewportHeight && anchor.top - popover.height - 6 > 0) {
      top = anchor.top - popover.height - 6;
    }
    setPosition({ top, left });
  }, [anchorRef, align]);
  useEffect(() => {
    const onKeyDown = (event) => {
      if (event.key === "Escape") {
        onClose?.();
      }
    };
    const onPointerDown = (event) => {
      if (!ref.current?.contains(event.target) && !anchorRef.current?.contains(event.target)) {
        onClose?.();
      }
    };
    document.addEventListener("keydown", onKeyDown);
    document.addEventListener("pointerdown", onPointerDown);
    return () => {
      document.removeEventListener("keydown", onKeyDown);
      document.removeEventListener("pointerdown", onPointerDown);
    };
  }, [onClose, anchorRef]);
  return (
    <UILayer>
      <UIFocusScope autoFocus={autoFocus} trap>
        <div ref={ref} role="dialog" aria-label={label} data-testid={testid} style={position ?? undefined} {...stylex.props(styles.base, styles.width(width), position !== null && styles.placed)}>
          {children}
        </div>
      </UIFocusScope>
    </UILayer>
  );
}
