import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";

const spin = stylex.keyframes({ from: { transform: "rotate(0deg)" }, to: { transform: "rotate(360deg)" } });

const styles = stylex.create({
  base: { display: "inline-block", borderRadius: "50%", borderStyle: "solid", borderColor: colors.divider, borderTopColor: colors.accent, animationName: spin, animationDuration: "0.8s", animationIterationCount: "infinite", animationTimingFunction: "linear" },
  size: (size) => ({ width: size, height: size, borderWidth: Math.max(2, size / 8) }),
});

export default function UISpinner({ size = 24, label = "Loading..." }) {
  return <span role="progressbar" aria-label={label} aria-busy="true" data-visualcompletion="loading-state" {...stylex.props(styles.base, styles.size(size))} />;
}
