// Profile pictures are an <svg> with a circular mask over an <image>, the
// structure the reference uses, plus the online dot and the story ring.
import { useId } from "react";
import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import { avatarTokens } from "ComponentTokens.stylex";

const styles = stylex.create({
  wrapper: { position: "relative", display: "inline-block", flexShrink: 0, lineHeight: 0, borderRadius: "50%" },
  size: (size) => ({ width: size, height: size }),
  svg: { display: "block", overflow: "visible" },
  ring: { position: "absolute", inset: -3, borderRadius: "50%", borderWidth: 2, borderStyle: "solid", borderColor: colors.storyRing },
  dot: (size) => ({
    position: "absolute",
    right: 0,
    bottom: 0,
    width: Math.max(8, Math.round(size / 4)),
    height: Math.max(8, Math.round(size / 4)),
    borderRadius: "50%",
    backgroundColor: colors.onlineDot,
    borderWidth: 2,
    borderStyle: "solid",
    borderColor: avatarTokens.background,
    boxSizing: "border-box",
  }),
});

export default function UIAvatar({ src, size = 40, label = "", online = false, ring = false, xstyle }) {
  const maskId = useId();
  const half = size / 2;
  return (
    <span {...stylex.props(styles.wrapper, styles.size(size), xstyle)}>
      <svg aria-label={label || undefined} role={label ? "img" : undefined} width={size} height={size} viewBox={`0 0 ${size} ${size}`} {...stylex.props(styles.svg)}>
        <mask id={maskId}>
          <circle cx={half} cy={half} r={half} fill="white" />
          {online ? <circle cx={size - size / 8} cy={size - size / 8} r={size / 7} fill="black" /> : null}
        </mask>
        <g mask={`url(#${maskId})`}>
          <image x="0" y="0" width={size} height={size} preserveAspectRatio="xMidYMid slice" href={src} data-visualcompletion="media-vc-image" />
          <circle cx={half} cy={half} r={half} fill="none" stroke="rgba(0,0,0,0.1)" strokeWidth="2" />
        </g>
      </svg>
      {ring ? <span data-visualcompletion="ignore" {...stylex.props(styles.ring)} /> : null}
      {online ? <span aria-hidden="true" {...stylex.props(styles.dot(size))} /> : null}
    </span>
  );
}
