// The base of every clickable thing: role and keyboard handling, hover and
// pressed state through a context, focus ring, and click logging.
import { useCallback, useMemo, useState } from "react";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { HoverStateContext } from "UIContexts";
import useLoggedCallback from "useLoggedCallback";

const styles = stylex.create({
  base: {
    position: "relative",
    display: "inline-flex",
    alignItems: "center",
    cursor: "pointer",
    border: 0,
    margin: 0,
    padding: 0,
    background: "none",
    color: "inherit",
    font: "inherit",
    textAlign: "inherit",
    textDecoration: "none",
    outline: { default: "none", ":focus-visible": `2px solid ${colors.focusRing}` },
    borderRadius: radii.md,
    WebkitTapHighlightColor: "transparent",
    userSelect: "none",
  },
  block: { display: "flex", width: "100%" },
  disabled: { cursor: "not-allowed", opacity: 0.5 },
  overlay: { position: "absolute", inset: 0, borderRadius: "inherit", pointerEvents: "none", opacity: 0, backgroundColor: colors.hoverOverlay },
  overlayHovered: { opacity: 1 },
  overlayPressed: { opacity: 1, backgroundColor: colors.pressOverlay },
});

export default function UIPressable({ as: Tag = "div", role = "button", onPress, label, logName, disabled = false, block = false, href, showOverlay = true, xstyle, children, testid, ...rest }) {
  const [hovered, setHovered] = useState(false);
  const [pressed, setPressed] = useState(false);
  const logged = useLoggedCallback(onPress, logName ?? label ?? "pressable");
  const onClick = useCallback(
    (event) => {
      if (disabled) {
        return;
      }
      if (href) {
        event.preventDefault();
      }
      logged(event);
    },
    [disabled, href, logged],
  );
  const onKeyDown = useCallback(
    (event) => {
      if (Tag !== "a" && Tag !== "button" && (event.key === "Enter" || event.key === " ")) {
        event.preventDefault();
        onClick(event);
      }
    },
    [Tag, onClick],
  );
  const hoverState = useMemo(() => ({ hovered, pressed }), [hovered, pressed]);
  return (
    <HoverStateContext.Provider value={hoverState}>
      <Tag
        {...rest}
        role={Tag === "a" || Tag === "button" ? undefined : role}
        href={href}
        tabIndex={disabled ? -1 : 0}
        aria-label={label}
        aria-disabled={disabled || undefined}
        data-testid={testid}
        onClick={onClick}
        onKeyDown={onKeyDown}
        onPointerEnter={() => setHovered(true)}
        onPointerLeave={() => {
          setHovered(false);
          setPressed(false);
        }}
        onPointerDown={() => setPressed(true)}
        onPointerUp={() => setPressed(false)}
        {...stylex.props(styles.base, block && styles.block, disabled && styles.disabled, xstyle)}
      >
        {children}
        {showOverlay ? <span data-visualcompletion="ignore" {...stylex.props(styles.overlay, hovered && styles.overlayHovered, pressed && styles.overlayPressed)} /> : null}
      </Tag>
    </HoverStateContext.Provider>
  );
}
