// Wraps an interaction handler so that each call logs a click event for the
// enclosing surface, with the flow it starts.
import { useCallback, useContext } from "react";
import { LoggingSurfaceContext } from "UIContexts";
import EventLogger from "EventLogger";
import FlowContext from "FlowContext";

export default function useLoggedCallback(callback, name) {
  const surface = useContext(LoggingSurfaceContext);
  return useCallback(
    (event) => {
      const flow = FlowContext.start(name);
      EventLogger.log("click", { surface: surface.path, name, flow: flow.id, x: event?.clientX ?? 0, y: event?.clientY ?? 0 });
      return callback?.(event);
    },
    [callback, name, surface],
  );
}
