import * as stylex from "@stylexjs/stylex";
import { colors } from "BaseTokens.stylex";
import UIIconPaths from "UIIconPaths";

const styles = stylex.create({
  base: { display: "inline-block", flexShrink: 0, verticalAlign: "middle", fill: "none", stroke: "currentColor", strokeWidth: 1.6, strokeLinecap: "round", strokeLinejoin: "round" },
  filled: { fill: "currentColor", stroke: "none" },
  primary: { color: colors.primaryIcon },
  secondary: { color: colors.secondaryIcon },
  accent: { color: colors.accent },
  disabled: { color: colors.disabledIcon },
  onAccent: { color: colors.onAccent },
  inherit: { color: "inherit" },
  size: (size) => ({ width: size, height: size }),
});

export default function UIIcon({ name, size = 20, color = "secondary", filled = false, label = null, xstyle }) {
  return (
    <svg viewBox="0 0 20 20" aria-hidden={label === null ? true : undefined} aria-label={label ?? undefined} role={label === null ? undefined : "img"} {...stylex.props(styles.base, filled && styles.filled, styles[color], styles.size(size), xstyle)}>
      <path d={UIIconPaths[name] ?? UIIconPaths.more} />
    </svg>
  );
}
