// The search field in the header. Focusing it opens the typeahead panel,
// whose module is loaded on first use.
import { Suspense, useCallback, useRef, useState } from "react";
import * as stylex from "@stylexjs/stylex";
import { colors, radii } from "BaseTokens.stylex";
import { searchInputTokens } from "ComponentTokens.stylex";
import UIIcon from "UIIcon.react";
import LazyModule from "LazyModule.react";

const styles = stylex.create({
  wrapper: { position: "relative" },
  field: { display: "flex", alignItems: "center", gap: 6, height: 40, width: 240, paddingInline: 12, borderRadius: radii.pill, backgroundColor: colors.inputBackground, boxSizing: "border-box" },
  input: { border: 0, outline: "none", background: "none", fontSize: searchInputTokens.fontSize, color: colors.primaryText, width: "100%", minWidth: 0 },
});

export default function SearchBox() {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const inputRef = useRef(null);
  const close = useCallback(() => {
    setOpen(false);
    setQuery("");
    inputRef.current?.blur();
  }, []);
  return (
    <div {...stylex.props(styles.wrapper)}>
      <label {...stylex.props(styles.field)}>
        <UIIcon name="search" size={16} />
        <input
          ref={inputRef}
          type="search"
          role="combobox"
          aria-expanded={open}
          aria-autocomplete="list"
          aria-label="Search"
          placeholder="Search Circlet"
          data-testid="search-input"
          value={query}
          onFocus={() => setOpen(true)}
          onChange={(event) => setQuery(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === "Escape") {
              close();
            }
          }}
          {...stylex.props(styles.input)}
        />
      </label>
      {open ? (
        <Suspense fallback={null}>
          <LazyModule name="SearchTypeaheadPanel.react" props={{ query, onClose: close, inputRef }} />
        </Suspense>
      ) : null}
    </div>
  );
}
